style.css:
@-moz-document domain("chat.openai.com") {
/* Заменяем логотип на "Reuters" */
  header img {
    content: url('https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Reuters_Logo.svg/1200px-Reuters_Logo.svg.png') !important;
    width: 150px;
    height: auto;
  }

  /* Меняем цвета на схему новостного сайта */
  body {
    background-color: #f8f9fa !important;
    color: #333 !important;
    font-family: Arial, sans-serif !important;
  }

  /* Заменяем заголовки */
  header h1 {
    content: "Reuters News" !important;
    font-size: 1.5em !important;
    color: #000 !important;
  }

  /* Скрываем нижние элементы интерфейса */
  footer, .chat-history {
    display: none !important;
  }

  /* Меняем ссылки */
  a {
    color: #0056b3 !important;
    text-decoration: none !important;
  }

  a:hover {
    text-decoration: underline !important;
  }
}
